  void prepareInvoice(){var proposal=propose();assertEquals("APPLIED",proposal.get("outcome"),proposal.toString());var order=dispatch(proposal,approve(proposal,"APPROVE"));assertEquals("APPLIED",order.get("outcome"),order.toString());line=order.get("poLineId").toString();ref=id();source=row("sourceNamespace","native-fixture","sourceKey",id(),"sourceVersion","1","lineId",line,"referenceId",ref,"scopeKind","PURCHASE","invoiceKind","COMMERCIAL","itemId",item,"quantity","100","unit","BOX","unitPrice","1","originalAmount","100","currency","EUR","occurredAt",AS_OF.toString(),"fxSnapshot",row("pair","EUR/KRW","rate","1500","date","2026-10-07","source","synthetic-fx","policyVersion","fx-v1","rounding","HALF_UP_SCALE_0"));String doc=attach(source,"PURCHASE_ORDER_LINE",line);invoiceSlots=row("invoiceKind","COMMERCIAL","originalAmount",row("value","100","currency","EUR"),"line",row("purchaseLineId",line,"receiptOccurrenceId",ref,"quantity",row("value","100","unit","BOX"),"unitPrice",row("value","1","currency","EUR")),"scopeKind","PURCHASE","evidence",doc,"fxSnapshot",source.get("fxSnapshot"));}
  String attach(Map<String,Object> original,String kind,String subject){try{byte[] data=json.writeValueAsBytes(original);return runtime.requestContext().run(c->{return records.attachDocument(new com.mulino.application.evidence.EvidenceRecords.DocumentInput(new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.valueOf(kind),subject),"native-fixture",id(),"application/json",com.mulino.adapters.blob.LocalBlobStore.hash(data),"synthetic-original",null),data);}).get("id").toString();}catch(Exception e){throw new IllegalStateException(e);}}
  Map<String,Object> settlement(String op,int rev,Map<String,Object> slots,String key){return runtime.requestContext().run(c->{return commands.execute(row("intentKind",op.equals("matchInvoice")||op.equals("confirmReceipt")?"COMMAND":"RECORD","capabilityId",op,"definitionVersion","1.0.0","expectedRevision",rev,"slots",slots,"provenance",Map.of(),"subjectRefs",List.of(),"commandIdempotencyKey",key));});}
  Map<String,Object> canonical(String iid,String kind,Map<String,Object> original,String quantity,String unit){String doc=attach(original,"INVOICE",iid);String eventKey=id();return runtime.requestContext().run(c->{var subject=new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.INVOICE,iid);var event=records.recordActivity(new com.mulino.application.evidence.EvidenceRecords.EventInput(subject,kind,"native-fixture",eventKey,"1",new com.mulino.domain.evidence.EvidenceTypes.EffectiveTime(AS_OF,null,"Asia/Seoul","SECOND"),com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,write(original),null,null));var claim=records.recordClaim(new com.mulino.application.evidence.EvidenceRecords.ClaimInput(event.get("id").toString(),doc,"source-reference",quantity,unit,com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,null));var review=reconciliation.match(context(),new com.mulino.application.evidence.EvidenceReconciliation.Review(claim.get("id").toString(),doc,iid,null,"fixture-v1","native-fixture:"+eventKey+":1",quantity,unit,AS_OF,"exact original source"),"matchSourceIdentity");assertEquals("MATCHED",review.get("outcome"),review.toString());var fact=reconciliation.link(context(),review.get("id").toString());return row("documentId",doc,"occurrenceId",fact.get("id"));});}
  String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
  @Test void invoiceGatewayPreservesFxAndClaimHasNoConfirmedEffect(){prepareInvoice();String key=id();int stock=count("mulino_inventory_QuantitySegments");var a=settlement("recordInvoice",1,invoiceSlots,key);assertEquals("APPLIED",a.get("outcome"),a.toString());assertEquals("150000",a.get("convertedAmount"));assertEquals(a,settlement("recordInvoice",1,invoiceSlots,key));assertEquals(1,count("mulino_trade_settlement_Invoices"));assertEquals("CONFLICT",settlement("recordInvoice",1,invoiceSlots,id()).get("outcome"));assertEquals(0,count("mulino_trade_settlement_Matches"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM mulino_trade_purchase_ExecutionEffects WHERE organizationId=? AND kind='INVOICED'",Integer.class,org));assertEquals(stock,count("mulino_inventory_QuantitySegments"));var noun=runtime.requestContext().run(ctx->{return queries.query(QueryRequests.parse("getObject",row("id",a.get("invoiceId"),"scope",row("organizationId",org,"itemId",item,"objectType","Invoice"))));});var verb=runtime.requestContext().run(ctx->{return queries.query(QueryRequests.parse("getSettlement",row("id",a.get("invoiceId"),"scope",row("organizationId",org,"itemId",item))));});assertEquals(noun.get("data"),verb.get("data"));assertThrows(Exception.class,()->jdbc.update("UPDATE mulino_trade_settlement_Invoices SET fxRate=1600 WHERE organizationId=?",org));invoiceSlots.put("originalAmount",row("value","101","currency","EUR"));assertEquals("CONFLICT",settlement("recordInvoice",1,invoiceSlots,key).get("outcome"));}
  @Test void staleUnauthorizedHaveZeroInvoiceEffects(){prepareInvoice();assertEquals("CONFLICT",settlement("recordInvoice",0,invoiceSlots,id()).get("outcome"));jdbc.update("UPDATE mulino_identity_CapabilityAssignments SET revokedAt=CURRENT_TIMESTAMP WHERE organizationId=? AND capabilityId='recordInvoice'",org);assertEquals("REJECTED",settlement("recordInvoice",1,invoiceSlots,id()).get("outcome"));assertEquals(0,count("mulino_trade_settlement_Invoices"));}
