  String receipt(String quantity){String range=id();Map<String,Object> original=row("rangeRootId",range,"startQuantity","0","quantity",quantity,"unit","BOX","itemId",item,"lotId",lot,"placeId",place,"workId",work,"occurredAt",AS_OF.toString());String doc=attach(original,"WORK",work);var fact=runtime.requestContext().run(c->{var event=records.recordActivity(new com.mulino.application.evidence.EvidenceRecords.EventInput(new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.WORK,work),"PHYSICAL_RECEIPT","native-fixture",id(),"1",new com.mulino.domain.evidence.EvidenceTypes.EffectiveTime(AS_OF,null,"Asia/Seoul","SECOND"),com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,write(original),null,null));var provisional=settlement("receiveProvisional",0,row("eventId",event.get("id"),"rangeRootId",range,"startQuantity","0","quantity",quantity,"unit","BOX","itemId",item,"lotId",lot,"placeId",place,"workId",work,"purchaseLineId",line,"ownerId",actor,"supervisorId",actor,"nextAction","대조한다","nextCheckAt",Instant.now().plusSeconds(3600).toString(),"occurredAt",AS_OF.toString()),id());assertEquals("APPLIED",provisional.get("outcome"),provisional.toString());var claim=records.recordClaim(new com.mulino.application.evidence.EvidenceRecords.ClaimInput(event.get("id").toString(),doc,"actual receipt",quantity,"BOX",com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,null));String eventKey=jdbc.queryForObject("SELECT externalEventId FROM mulino_evidence_Events WHERE ID=?",String.class,event.get("id"));var review=reconciliation.match(context(),new com.mulino.application.evidence.EvidenceReconciliation.Review(claim.get("id").toString(),doc,range,null,"fixture-v1","native-fixture:"+eventKey+":1",quantity,"BOX",AS_OF,"real receipt"),"matchSourceIdentity");assertEquals("MATCHED",review.get("outcome"),review.toString());var canonical=reconciliation.link(context(),review.get("id").toString());var confirm=settlement("confirmReceipt",0,row("receiptId",((Map<?,?>)provisional.get("effects")).get("receiptId"),"lotId",lot,"canonicalOccurrenceId",canonical.get("id")),id());assertEquals("APPLIED",confirm.get("outcome"),confirm.toString());return canonical;});return fact.get("id").toString();}
