  /** s4-settle-00/07 (D13·§6 정산): an excess second receipt bills only its recognized 40 of 45; INVOICED never exceeds recognition. */
  @Test void excessReceiptIsBilledOnlyUpToRecognizedContribution(){prepareInvoice();String first=receipt("60"),second=receipt("45");
    decimalEquals("5",jdbc.queryForObject("SELECT excessQuantity FROM mulino_trade_purchase_ReceiptCredits WHERE organizationId=? AND occurrenceId=?",java.math.BigDecimal.class,org,second));
    var s1=invoiceSource(first,"COMMERCIAL","60","1","60");String i1=invoice(s1);var m1=matchOf(i1,s1);assertEquals("APPLIED",m1.get("outcome"),m1.toString());assertEquals("MATCHED",m1.get("businessStatus"));
    var s2=invoiceSource(second,"COMMERCIAL","45","1","45");String i2=invoice(s2);var m2=matchOf(i2,s2);assertEquals("APPLIED",m2.get("outcome"),m2.toString());
    assertEquals("DIFFERENCE",m2.get("businessStatus"),m2.toString());assertEquals("UNSATISFIED",m2.get("settlementResult"));decimalEquals("5",m2.get("quantityDifference"));decimalEquals("5",m2.get("originalDifference"));decimalEquals("40",m2.get("receivedQuantity"));
    decimalEquals("40",jdbc.queryForObject("SELECT receivedQuantity FROM mulino_trade_settlement_Matches WHERE organizationId=? AND invoiceId=?",java.math.BigDecimal.class,org,i2));assertEquals(1,openSettlementDuties());
    assertEquals("SATISFIED",settlementOf(i1).get("result"));assertEquals("UNSATISFIED",settlementOf(i2).get("result"));
    // INVOICED execution is the recognized 60+40, not the billed 105; a DOMESTIC_TAX reference of the same 60 adds nothing.
    decimalEquals("100",invoiced());var tax=invoiceSource(first,"DOMESTIC_TAX","60","1","60");String i3=invoice(tax);var m3=matchOf(i3,tax);assertEquals("APPLIED",m3.get("outcome"),m3.toString());assertEquals("MATCHED",m3.get("businessStatus"));decimalEquals("100",invoiced());
    // s4-settle-04: a MATCHED invoice has no open difference, so no adjustment can manufacture an ownerless one.
    settlementManager();var onMatched=propose(i1,"3");assertEquals("REJECTED",onMatched.get("outcome"),onMatched.toString());assertEquals("SETTLEMENT_DIFFERENCE_NOT_OPEN",code(onMatched));assertEquals(0,count("mulino_trade_settlement_Adjustments"));assertEquals("SATISFIED",settlementOf(i1).get("result"));}

  /** s4-settle-01/03 (§5.3·§6): an amount adjustment cannot discharge a quantity difference; zero adjustments are not evidence. */
  @Test void amountAdjustmentCannotResolveQuantityDifference(){prepareInvoice();String r=receipt("100");var s=invoiceSource(r,"COMMERCIAL","120","1","120");String iid=invoice(s);var m=matchOf(iid,s);assertEquals("APPLIED",m.get("outcome"),m.toString());decimalEquals("20",m.get("quantityDifference"));decimalEquals("20",m.get("originalDifference"));settlementManager();
    var proposed=propose(iid,"20");assertEquals("APPLIED",proposed.get("outcome"),proposed.toString());var confirmed=confirm(iid,proposed,"20");assertEquals("APPLIED",confirmed.get("outcome"),confirmed.toString());decimalEquals("0",confirmed.get("settlementDifference"));
    String duty=dutyOf(iid);var resolved=resolveDuty(duty,confirmed.get("adjustmentId").toString());assertEquals("HELD",resolved.get("outcome"),resolved.toString());assertEquals("OPEN",status(duty));
    var view=settlementOf(iid);assertEquals("UNSATISFIED",view.get("result"));decimalEquals("20",view.get("quantityDifference"));decimalEquals("0",view.get("settlementDifference"));
    var zero=propose(iid,"0");assertEquals("REJECTED",zero.get("outcome"),zero.toString());assertEquals("TYPE_INVALID",code(zero));}

  /** s4-settle-04/08 (§5.3 의무 비부활·§6): after the duty is RESOLVED no stale or new adjustment can reopen an ownerless difference. */
  @Test void resolvedDifferenceAcceptsNoFurtherAdjustment(){prepareInvoice();String r=receipt("100");var s=invoiceSource(r,"COMMERCIAL","100","1.05","105");String iid=invoice(s);var m=matchOf(iid,s);assertEquals("APPLIED",m.get("outcome"),m.toString());settlementManager();
    var first=propose(iid,"5");var stale=propose(iid,"5");assertEquals("APPLIED",stale.get("outcome"),stale.toString());var confirmed=confirm(iid,first,"5");assertEquals("APPLIED",confirmed.get("outcome"),confirmed.toString());
    String duty=dutyOf(iid);var resolved=resolveDuty(duty,confirmed.get("adjustmentId").toString());assertEquals("APPLIED",resolved.get("outcome"),resolved.toString());assertEquals("RESOLVED",status(duty));assertEquals("SATISFIED",settlementOf(iid).get("result"));
    var late=confirm(iid,stale,"5");assertEquals("REJECTED",late.get("outcome"),late.toString());assertEquals("SETTLEMENT_DIFFERENCE_NOT_OPEN",code(late));var again=propose(iid,"3");assertEquals("REJECTED",again.get("outcome"),again.toString());
    assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM mulino_trade_settlement_Adjustments WHERE organizationId=? AND status='CONFIRMED'",Integer.class,org));var view=settlementOf(iid);assertEquals("SATISFIED",view.get("result"));decimalEquals("0",view.get("settlementDifference"));assertEquals("RESOLVED",status(duty));}

  /** s4-settle-02/09 (§4.3): a receipt whose verification chain was superseded is re-checked at match, read and closure time. */
  @Test void supersededReceiptChainUnverifiesSettlementAndBlocksMatchAndClosure(){prepareInvoice();String r=receipt("100");var s=invoiceSource(r,"COMMERCIAL","100","1.05","105");String iid=invoice(s);var m=matchOf(iid,s);assertEquals("APPLIED",m.get("outcome"),m.toString());settlementManager();
    var proposed=propose(iid,"5");var confirmed=confirm(iid,proposed,"5");assertEquals("APPLIED",confirmed.get("outcome"),confirmed.toString());var before=settlementOf(iid);assertEquals("SATISFIED",before.get("result"));
    // The evidence owner corrects the receipt claim (correctEvidence); the canonical receipt then has no current verified chain.
    grantCapability("correctEvidence");
    var claim=jdbc.queryForMap("SELECT c.ID,c.eventId,c.documentVersionId FROM mulino_evidence_Claims c JOIN mulino_evidence_Verifications v ON v.claimId=c.ID WHERE v.organizationId=? AND v.canonicalOccurrenceId=?",org,r);
    runtime.requestContext().run(ctx->{return records.recordClaim(new com.mulino.application.evidence.EvidenceRecords.ClaimInput(claim.get("eventid").toString(),claim.get("documentversionid").toString(),"corrected receipt claim","100","BOX",com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,claim.get("id").toString()));});
    var after=settlementOf(iid);assertEquals("UNVERIFIED",after.get("result"),after.toString());assertEquals("CURRENT",before.get("contributionState"));assertEquals("UNVERIFIED",after.get("contributionState"));
    String duty=dutyOf(iid);var resolved=resolveDuty(duty,confirmed.get("adjustmentId").toString());assertEquals("HELD",resolved.get("outcome"),resolved.toString());assertEquals("OPEN",status(duty));
    var s2=invoiceSource(r,"COMMERCIAL","100","1","100");String second=invoice(s2);var m2=matchOf(second,s2);assertEquals("HELD",m2.get("outcome"),m2.toString());assertEquals("EVIDENCE_UNVERIFIED",code(m2));assertEquals(1,count("mulino_trade_settlement_Matches"));decimalEquals("100",invoiced());}

  /** s4-settle-05 (§6·D19): an original carrying an FX snapshot cannot be recorded without the snapshot slot. */
  @Test void fxSnapshotInOriginalCannotBeDroppedBySlot(){prepareInvoice();invoiceSlots.remove("fxSnapshot");var dropped=settlement("recordInvoice",1,invoiceSlots,id());assertEquals("HELD",dropped.get("outcome"),dropped.toString());assertEquals("EVIDENCE_UNVERIFIED",code(dropped));assertEquals(0,count("mulino_trade_settlement_Invoices"));}

  /** s4-settle-06 + P3 (§4.3·§6): corrections must name an attested original, open review duty and keep the original UNVERIFIED. */
  @Test void creditNoteKeepsOriginalUnverifiedWithOwnedReviewDuty(){prepareInvoice();String r=receipt("100");var s=invoiceSource(r,"COMMERCIAL","100","1","100");String original=invoice(s);var m=matchOf(original,s);assertEquals("MATCHED",m.get("businessStatus"),m.toString());assertEquals("SATISFIED",settlementOf(original).get("result"));
    var orphan=invoiceSource(r,"CREDIT_NOTE","5","1","5");var rejected=invoiceCommand(orphan);assertEquals("REJECTED",rejected.get("outcome"),rejected.toString());
    var linkedCommercial=invoiceSource(r,"COMMERCIAL","5","1","5");linkedCommercial.put("relatedInvoiceId",original);assertEquals("REJECTED",invoiceCommand(linkedCommercial).get("outcome"));
    var unattested=invoiceSource(r,"CREDIT_NOTE","5","1","5");var slots=row("invoiceKind","CREDIT_NOTE","originalAmount",row("value","5","currency","EUR"),"line",row("purchaseLineId",line,"receiptOccurrenceId",r,"quantity",row("value","5","unit","BOX"),"unitPrice",row("value","1","currency","EUR")),"scopeKind","PURCHASE","evidence",attach(unattested,"PURCHASE_ORDER_LINE",line),"relatedInvoiceId",original);assertEquals("HELD",settlement("recordInvoice",1,slots,id()).get("outcome"));
    assertEquals(1,count("mulino_trade_settlement_Invoices"));assertEquals(0,openSettlementDuties());
    var credit=invoiceSource(r,"CREDIT_NOTE","5","1","5");credit.put("relatedInvoiceId",original);var recorded=invoiceCommand(credit);assertEquals("APPLIED",recorded.get("outcome"),recorded.toString());String cid=recorded.get("invoiceId").toString();
    assertEquals(1,openSettlementDuties());String duty=dutyOf(cid);assertEquals("OPEN",status(duty));
    var view=settlementView(original);var result=(Map<?,?>)view.get("settlement");assertEquals("UNVERIFIED",result.get("result"),view.toString());assertEquals(true,result.get("correctionReviewOpen"));assertEquals(1,((List<?>)view.get("corrections")).size());
    assertTrue(((List<?>)view.get("obligations")).stream().anyMatch(x->duty.equals(((Map<?,?>)x).get("ID"))||duty.equals(((Map<?,?>)x).get("id"))),view.get("obligations").toString());
    var byAnything=resolveDuty(duty,cid);assertEquals("HELD",byAnything.get("outcome"),byAnything.toString());assertEquals("OPEN",status(duty));}

  /** P3 (§6 지급참조): one remittance may settle several invoices, recorded once per invoice, duplicates are a typed CONFLICT. */
  @Test void oneRemittanceReferencesSeveralInvoicesOncePerInvoice(){prepareInvoice();String r=receipt("100");String a=invoice(invoiceSource(r,"COMMERCIAL","50","1","50")),b=invoice(invoiceSource(r,"COMMERCIAL","50","1","50"));String remittance="TRF-"+id();
    java.util.function.Function<String,Map<String,Object>> pay=iid->{Map<String,Object> original=row("invoiceId",iid,"amount","50","currency","EUR","externalPaymentReference",remittance,"observedAt",AS_OF.toString(),"occurredAt",AS_OF.toString(),"externalEventId",id());var proof=canonical(iid,"PAYMENT_REFERENCE",original,null,null);return settlement("recordPaymentReference",1,row("invoiceId",iid,"amount",row("value","50","currency","EUR"),"externalPaymentReference",remittance,"observedAt",AS_OF.toString(),"evidence",proof.get("documentId"),"canonicalOccurrenceId",proof.get("occurrenceId")),id());};
    assertEquals("APPLIED",pay.apply(a).get("outcome"));var second=pay.apply(b);assertEquals("APPLIED",second.get("outcome"),second.toString());var duplicate=pay.apply(a);assertEquals("CONFLICT",duplicate.get("outcome"),duplicate.toString());assertEquals("PAYMENT_REFERENCE_ALREADY_RECORDED",code(duplicate));
    assertEquals(2,count("mulino_trade_settlement_PaymentReferences"));assertEquals(0,jdbc.queryForObject("SELECT sum(bankEffect) FROM mulino_trade_settlement_PaymentReferences WHERE organizationId=?",java.math.BigDecimal.class,org).signum());}

  // s4j closure 2 (opus[2], plan §6 정산, §4.3, §5.3): a receipt canonical is never superseded by a new canonical, so the corrected
  // receipt chain reaches settlement on the evidence-correction path. The request knownAt is fixed before the superseding event is
  // recorded (the real clock moves), as in the public correctEvidence command.
  @Autowired com.mulino.application.evidence.EvidenceCorrectionImpact correctionImpact;
  @Test void correctedReceiptChainOpensAnOwnedSettlementDifferenceForItsPurchaseMatch(){prepareInvoice();ref=receipt("100");source.put("referenceId",ref);source.remove("fxSnapshot");invoiceSlots.remove("fxSnapshot");invoiceSlots.put("evidence",attach(source,"PURCHASE_ORDER_LINE",line));invoiceSlots.put("line",row("purchaseLineId",line,"receiptOccurrenceId",ref,"quantity",row("value","100","unit","BOX"),"unitPrice",row("value","1","currency","EUR")));
    String iid=settlement("recordInvoice",1,invoiceSlots,id()).get("invoiceId").toString();var fact=canonical(iid,"INVOICE",source,"100","BOX");var match=settlement("matchInvoice",1,row("invoiceId",iid,"canonicalOccurrenceId",fact.get("occurrenceId"),"evidence",fact.get("documentId")),id());assertEquals("MATCHED",match.get("businessStatus"),match.toString());
    String open="SELECT count(*) FROM mulino_work_read_ObligationReferences WHERE organizationId=? AND kind='SETTLEMENT_DIFFERENCE' AND status='OPEN'";assertEquals(0,jdbc.queryForObject(open,Integer.class,org));
    var original=jdbc.queryForMap("SELECT e.ID,e.externalEventId,e.payload FROM mulino_evidence_Events e JOIN mulino_evidence_Claims c ON c.eventId=e.ID JOIN mulino_evidence_Verifications v ON v.claimId=c.ID WHERE v.canonicalOccurrenceId=?",ref);
    String grantId=jdbc.queryForObject("SELECT grantId FROM mulino_identity_GrantActions WHERE organizationId=? AND capabilityId='recordActivity' LIMIT 1",String.class,org);insert("mulino_identity_GrantActions",row("organizationId",org,"grantId",grantId,"capabilityId","correctEvidence"));insert("mulino_identity_CapabilityAssignments",row("organizationId",org,"ID",id(),"actorId",actor,"capabilityId","correctEvidence","scopeKind","ORGANIZATION","scopeId",org,"validFrom",Timestamp.from(Instant.now().minusSeconds(3600)),"validUntil",Timestamp.from(Instant.now().plusSeconds(3600))));
    Instant requestKnownAt=Instant.now();
    runtime.requestContext().run(c->{return new org.springframework.transaction.support.TransactionTemplate(transactions).execute(st->{var corrected=records.recordActivity(new com.mulino.application.evidence.EvidenceRecords.EventInput(new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.WORK,work),"PHYSICAL_RECEIPT","native-fixture",original.get("externalEventId").toString(),"2",new com.mulino.domain.evidence.EvidenceTypes.EffectiveTime(AS_OF,null,"Asia/Seoul","SECOND"),com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,original.get("payload").toString(),original.get("id").toString(),null));
      correctionImpact.apply(new DomainContext(org,actor,actor,requestKnownAt,requestKnownAt),new com.mulino.application.evidence.EvidenceCorrectionImpact.Correction(original.get("id").toString(),corrected.get("id").toString(),Set.of(work),Set.of()));return corrected;});});
    var duties=jdbc.queryForList("SELECT o.ownerId,o.nextAction,o.nextCheckAt,r.sourceId,r.scopeJson FROM mulino_work_read_ObligationReferences o JOIN mulino_responsibility_Roots r ON r.ID=o.rootId WHERE o.organizationId=? AND o.kind='SETTLEMENT_DIFFERENCE' AND o.status='OPEN'",org);
    assertEquals(1,duties.size(),duties.toString());assertEquals(ref,duties.getFirst().get("sourceid"));assertEquals(actor,duties.getFirst().get("ownerid"));assertNotNull(duties.getFirst().get("nextaction"));assertNotNull(duties.getFirst().get("nextcheckat"));assertTrue(duties.getFirst().get("scopejson").toString().contains("UNVERIFIED"),duties.toString());
    var view=(Map<?,?>)((Map<?,?>)runtime.requestContext().run(ctx->{return queries.query(QueryRequests.parse("getSettlement",row("id",iid,"scope",row("organizationId",org,"itemId",item))));}).get("data")).get("settlement");assertEquals("UNVERIFIED",view.get("contributionState"),view.toString());assertEquals(true,view.get("differenceDutyOpen"),view.toString());}
